import{_ as l,l as i,o as e,c as s,v as t,p as n,x as r,d as p,i as E,S as R}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"CVaR 优化","description":"","frontmatter":{"title":"CVaR 优化","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/cvar-opt.md","filePath":"quant/cvar-opt.md","lastUpdated":1789023840000}'),c={name:"quant/cvar-opt.md"};function h(V,a,m,d,C,B){const o=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="cvar-优化" tabindex="-1">CVaR 优化 <a class="header-anchor" href="#cvar-优化" aria-label="Permalink to &quot;CVaR 优化&quot;">​</a></h1><div class="epigraph"><p>把超过分位数之后的损失均值写成对辅助变量的凸函数，最小化尾部就变成情景上的线性规划，而不必去最小化一个非凸的 VaR。</p><footer>—— Rockafellar and Uryasev, Optimization of Conditional Value-at-Risk, Journal of Risk, 2000</footer></div><p><a href="/quant/markowitz">Markowitz</a> 用 \\(w^\\top\\Sigma w\\) 当风险，对称、二次、对估计误差敏感。<a href="/quant/expected-shortfall">Expected Shortfall</a> 一文写的是度量：ES / CVaR 连贯、对尾巴形状收费。组合构建要问的是如何<strong>选 \\(w\\)</strong>。VaR 作为分位数对权重一般非凸，不能直接丢进求解器。Rockafellar 与 Uryasev（2000, 2002）证明 CVaR 等于一个对阈值 \\(c\\) 的最小化，且在损失仿射于 \\(w\\) 时，对 \\((w,c)\\) 联合凸；用情景样本后成为 LP。本篇写这个可优化形式、均值–CVaR 前沿、与二次风险的对照，以及情景不足时优化器如何把「最坏那几天」当成可重复的 alpha。它补的是选择问题，不是再讲一遍公理。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>投资人讨厌的是左尾，不是方差里的上涨腿。期权卖方、信用、趋势拥挤，均方最优可以看起来分散，CVaR 却几乎全来自同一类缺口。直接最小化 \\(\\mathrm{VaR}_\\alpha(w)\\) 会遇到非凸、非光滑，解依赖求解器与初值，监管套利式的「把损失刚好藏在分位外」在优化里也会出现。需要一个对尾巴敏感、又对 \\(w\\) 凸的目标，使分散化被奖励（次可加），并且能加线性约束：预算、<a href="/quant/long-short-constraints">多空</a>、行业中性、换手。</p><p>CVaR 优化并不自动比 Markowitz 更稳健。尾巴的估计比 \\(\\Sigma\\) 更吵：\\(n(1-\\alpha)\\) 个情景决定目标，99% 下十年日度数据只有二十来个点。优化器会把这二十天的特有结构（当时哪些名字跌）写成永久的避险方向，这是尾部版的误差最大化。问题是把 Rockafellar–Uryasev 的凸形式用对，再对情景集做收缩、分块自助或压力叠加，而不是指望换目标函数就解决估计。</p><h3 id="为什么不直接优化-var" tabindex="-1">为什么不直接优化 VaR <a class="header-anchor" href="#为什么不直接优化-var" aria-label="Permalink to &quot;为什么不直接优化 VaR&quot;">​</a></h3><p>VaR 的接受集不凸，两个局部最优之间的组合可以更差。权重微调若让某一情景刚好跨过或跨出分位，目标会跳。求解器报告的「最优 VaR 组合」往往不可复现。CVaR 对超过阈值的部分做积分（样本上是平均），对权重几乎处处可微（辅助变量形式里是线性），次可加保证合并不增风险。监管从 VaR 转向 ES，与优化从方差转向 CVaR，是同一几何在两个部门的投影：都在对分位数以外的形状收费。</p><p><span class="marginnote">连续分布上 CVaR 与 ES 一致，最优辅助变量 \\(c^\\star\\) 就是 VaR。因此「最小化 CVaR」会顺带给出一个 VaR，但目标与约束必须写 CVaR，不能在求解过程中改成钉 VaR 限额——钉分位数会把问题变回非凸。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Rockafellar–Uryasev 的表示：损失 \\(L(w,r)=-w^\\top r\\)（或相对基准），</p> \\[\\mathrm{CVaR}_\\alpha(w)=\\min_{c\\in\\mathbb{R}}\\Bigl\\{c+\\frac{1}{1-\\alpha}\\mathbb{E}\\big[(L(w,r)-c)^+\\big]\\Bigr\\}. \\]<p>经验测度 \\(\\{r_s\\}_{s=1}^S\\) 下引入松弛 \\(\\zeta_s\\ge 0\\)，</p> \\[\\min_{w,c,\\zeta}\\quad c+\\frac{1}{(1-\\alpha)S}\\sum_{s=1}^S\\zeta_s \\]<p>约束 \\(\\zeta_s\\ge -w^\\top r_s-c\\)，\\(\\mathbf{1}^\\top w=1\\)，以及制度约束。这是 LP（再加二次交易成本则是 QP）。均值约束 \\(w^\\top\\hat\\mu\\ge\\mu_p\\) 画出均值–CVaR 前沿，对应均方前沿的尾部版。无均值约束时得到最小 CVaR 组合，类似 GMV，对 \\(\\mu\\) 免疫、对尾巴情景极度敏感。</p><p>情景从哪来：历史窗口；对 \\(\\hat\\Sigma\\) 做蒙特卡洛（椭圆，则 CVaR 与方差只差常数倍，最优与 Markowitz 重合，白做）；对残差做 bootstrap 或 copula–GARCH，使尾依赖进入路径；压力情景加权。椭圆新息下不必换目标；非椭圆、非对称、违约指示，LP 才真正偏离二次。混合目标 \\(\\lambda w^\\top\\Sigma w+(1-\\lambda)\\mathrm{CVaR}\\) 用来在「日常风险」与「崩盘」之间插值，避免纯 CVaR 只由几十个点决定。</p><h3 id="约束、可交易性与求解" tabindex="-1">约束、可交易性与求解 <a class="header-anchor" href="#约束、可交易性与求解" aria-label="Permalink to &quot;约束、可交易性与求解&quot;">​</a></h3><p>行业中性、杠杆、换手都是线性或线性化后进入同一 LP，这是相对「先最小方差再手工裁尾」的优点：一阶条件在同一套约束下成立。计算上 \\(S\\) 万级、\\(\\alpha=0.99\\) 仍可解；真正的成本是生成一致的情景（同一套风险因子、同一套流动性假设）。若每条路径的损失未计入冲击，优化器会在压力日对非流动性名字做虚假对冲。<a href="/quant/tcost-opt">交易成本感知</a> 应把冲击写进 \\(L_s\\)，否则 CVaR 最优在可交易世界上不可达。</p><p>Rockafellar–Uryasev 也可以对 CVaR 做约束、最大化期望，对偶于最小化 CVaR。限额制度（「97.5% ES 不超过资本的 x%」）用约束形式更自然。多个期限、多个 \\(\\alpha\\) 可以并列，可行集变紧，接近监管式的 FRTB 多地平线，估计更饿数据。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是<strong>对超阈损失的平均做梯度下降（在 LP 里是单纯形/内点）</strong>：某个情景里损失大，对当时大仓位的名字产生向下的影子价格，优化器减仓或对冲，直到再减一单位在约束下不再降低平均超阈。分散化被次可加奖励：两个同爆的腿，合并 CVaR 接近相加，对冲被识别为无效。高斯 Copula 式的「平时分散、极端同爆」若被情景集捕捉，CVaR 会收费；若情景集是多元正态，它看不见同爆，最优退回均方。</p><p>与 Markowitz 的解可以差很远：方差最优超配「高波动但上涨腿也大」的资产（趋势、卖出虚值），CVaR 最优会避开左尾厚的一侧。卖出期权在均方里像高夏普，在历史 CVaR 里像定时炸弹——前提是窗口里炸过。窗口里没炸过，CVaR 优化与均方一样会被卖出期权骗，这是样本的错，不是公式的错。应把压力路径（1987、2008、闪崩）以最低权重强制进情景集，等于对经验测度做有观点的倾斜，精神上接近 <a href="/quant/bl-views">BL 观点</a> 对 \\(\\mu\\) 做的事，只是作用在损失测度上。</p><p><span class="marginnote">经验 CVaR 对单个极值敏感：错记一次脉冲可以让某只股票永远被零权重。清洗规则与 winsorize 会改最优，必须事前冻结，不能看着最优权重再删情景。这是尾部优化的治理，不是统计细节。</span></p><h3 id="估计误差与正则" tabindex="-1">估计误差与正则 <a class="header-anchor" href="#估计误差与正则" aria-label="Permalink to &quot;估计误差与正则&quot;">​</a></h3><p>情景少，有效自由度是「坏日子的种类」而不是 \\(S\\)。正则包括：对 \\(w\\) 加 \\(\\ell_2\\) 或换手惩罚；用因子把 \\(r_s=B f_s+\\varepsilon_s\\)，只在因子 CVaR 上优化、特异风险二次惩罚；把 \\(\\alpha\\) 从 0.99 降到 0.95 以增加有效尾样本，再用压力加码极端。Yamai–Yoshiba 指出厚尾下 ES 估计方差可以大于 VaR；优化是把这个吵的标量再对 \\(w\\) 求导，噪声更大。样本外必须用滚动：在 \\(t\\) 用 \\(t\\) 以前情景优化，评估 \\(t+1\\) 的实现损失是否真的更薄，而不是样本内 CVaR 降了多少——样本内必然降。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要在椭圆假设下换 CVaR 还宣称改善了尾部：此时它与方差只差尺度。不要用未扣流动性的中间价路径做卖方期权或信用的 CVaR 最优。不要把 FRTB 的 ES 资本公式直接当组合目标：监管 ES 有压力期校准、流动性期限与风险类加总，和 Rockafellar–Uryasev 的单期组合 LP 不是同一个数。多空、非线性工具要使 \\(L(w,r)\\) 仍对 \\(w\\) 凸（或分段线性），期权的损失对现货非线性，应用希腊或全定价路径，不能把 delta 当 \\(w\\) 再套线性损失。</p><p>连贯性不包含动态：单期最小 CVaR 在多期再平衡、中间追加保证金下不必时间一致。多期要用动态风险度量或至少把路径上的强平写进 \\(L\\)。与 <a href="/quant/erc">ERC</a> 结合的 CVaR 平价，会计可以做，优化变成更吵的一层，只适合资产类 \\(N\\) 很小的时候。</p><p><span class="marginnote">「我们优化的是连贯风险度量」不能当样本外护身符。连贯地拟合了二十个历史坏日，仍然可能对第二十一个坏日一无所知。公理约束的是度量如何对待分散化，不是模型是否完整。</span></p>',29)),(e(),n(R,null,{default:r(()=>[E(o,{id:"mermaid-81",class:"mermaid",graph:"flowchart%20TD%0A%20%20SC%5B%22%E6%83%85%E6%99%AF%E6%8D%9F%E5%A4%B1%20L_s(w)%22%5D%20--%3E%20RU%5B%22min_c%20c%20%2B%201%2F(1-%CE%B1)%20E%5B(L-c)%2B%5D%22%5D%0A%20%20RU%20--%3E%20LP%5B%22%E8%BE%85%E5%8A%A9%E5%8F%98%E9%87%8F%20%CE%B6_s%20%E2%86%92%20LP%20%2F%20QP%22%5D%0A%20%20LP%20--%3E%20FR%5B%22%E5%9D%87%E5%80%BC-CVaR%20%E5%89%8D%E6%B2%BF%22%5D%0A%20%20VAR%5B%22%E7%9B%B4%E6%8E%A5%20min%20VaR%22%5D%20--%3E%20NC%5B%22%E9%9D%9E%E5%87%B8%2C%20%E4%B8%8D%E5%8F%AF%E9%9D%A0%22%5D%0A%20%20ELL%5B%22%E6%A4%AD%E5%9C%86%E6%96%B0%E6%81%AF%22%5D%20--%3E%20EQ%5B%22%E4%B8%8E%20Markowitz%20%E5%8F%AA%E5%B7%AE%E5%B0%BA%E5%BA%A6%22%5D%0A%20%20FAT%5B%22%E9%9D%9E%E6%A4%AD%E5%9C%86%20%2F%20%E5%B0%BE%E4%BE%9D%E8%B5%96%22%5D%20--%3E%20DIFF%5B%22CVaR%20%E6%9C%80%E4%BC%98%E5%81%8F%E7%A6%BB%E5%9D%87%E6%96%B9%22%5D%0A%20%20LP%20--%3E%20REG%5B%22%E6%83%85%E6%99%AF%E5%B0%91%20%E2%86%92%20%E6%8D%A2%E6%89%8B%E6%83%A9%E7%BD%9A%20%2F%20%E5%9B%A0%E5%AD%90%20CVaR%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Rockafellar–Uryasev（2000）把 CVaR 写成对阈值 \\(c\\) 的凸最小化，情景下成为可加线性约束的 LP，使尾部组合选择可解。</li><li>椭圆世界里均值–CVaR 与均值–方差重合；非椭圆、非对称时最优才真正离开 Markowitz。</li><li>有效样本是超阈情景的种类，不是 \\(S\\)；必须正则、滚动评价，并考虑把压力路径强制进测度。</li><li>VaR 不宜作为优化目标；CVaR 可作目标或资本约束，与制度限额对齐时用约束形式更自然。</li><li>损失定义须含冲击与非线性定价，否则「最优」不可交易。</li><li>出处：Rockafellar &amp; Uryasev, <em>Journal of Risk</em>, 2000；展开见 <em>Journal of Banking &amp; Finance</em>, 2002；连贯性背景见 Artzner et al., 1999；ES 定义澄清见 Acerbi &amp; Tasche, 2002。</li></ul>',2))])}const f=l(c,[["render",h]]);export{u as __pageData,f as default};
